import { expect, test } from 'bun:test';
import { join } from 'node:path';
import { ExtractionBatch } from '../src/domain/entities/extraction-batch';
import { MemoryEventEnvelope } from '../src/domain/entities/memory-event';
import { OwnedDatabase } from '../src/infrastructure/database/owned-database';
import { createSchema } from '../src/infrastructure/database/schema';
import { appendMemoryEvent, rebuildProjections } from '../src/infrastructure/database/event-log';
import { SqliteFactRepository } from '../src/infrastructure/database/repositories/fact-repository';
import { createOwnedTestDirectory } from '../tests/helpers/owned-test-directory';
test('complete extraction batch source replays its ordered effects',async()=>{
 const storage=createOwnedTestDirectory('memory-codec-reader-'),db=new OwnedDatabase(join(storage.dir,'synthetic.db')),log=join(storage.dir,'events','events-a.jsonl');
 try{
  createSchema(db);
  const batch=ExtractionBatch.fromJSON({version:1,sessionId:'synthetic',inputIdentity:'v1:'+'a'.repeat(64),project:'synthetic',provider:'synthetic',model:'synthetic',extractedAt:'2026-09-28T10:00:00.000Z',result:{added:1,updated:0,superseded:0,skipped:0},facts:[{uuid:'fact-one',type:'learning',content:'synthetic batch fact'}]});
  const event=MemoryEventEnvelope.create({eventId:'batch-one',machineId:'synthetic',sequence:1,kind:'projection',operation:'add',occurredAt:new Date(batch.toJSON().extractedAt),observedAt:new Date(batch.toJSON().extractedAt),scope:{project:'synthetic',visibility:'project'},provenance:{source:'memory-extraction',actor:'memory',method:'extraction-batch-v1',sourceIds:['synthetic']},privacy:{redactionState:'none',containsSensitiveContent:false},consent:{status:'not_required',scopes:[]},causality:{parentEventIds:[],relatedEventIds:[],supersedesEventIds:[]},payload:{extractionBatch:batch.toJSON()}});
  await appendMemoryEvent(event,log);
  await expect(rebuildProjections(db,log).catch(error=>{console.log(JSON.stringify({message:error.message,cause:String(error.cause)}));throw error;})).resolves.toBeUndefined();
  expect((await new SqliteFactRepository(db).findByProject('synthetic')).map(f=>f.content)).toEqual(['synthetic batch fact']);
 }finally{db.close();storage.cleanup();}
});

