import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {join,dirname,resolve} from 'node:path';
import {createCoverageMap} from 'istanbul-lib-coverage';
import {instrumentTypeScriptWithCoverage} from '../scripts/run-istanbul-bun-coverage';
import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
import {sourceHash} from '../scripts/quality-inventory';
const root=process.cwd(),storage=createOwnedTestDirectory('memory-remote-diagnostic-');
const paths=["src/domain/entities/extraction-batch.ts","src/domain/entities/extraction-batch.test.ts"];

const tests=paths.filter(path=>path.endsWith('.test.ts'));
const mode=process.argv[2]??'measure';if(!['measure','faults'].includes(mode))throw Error('Invalid mode');
const originals=new Map(paths.map(path=>[path,readFileSync(path,'utf8')]));
const typePath='src/domain/ports/operation-admission.ts',typeHash=sourceHash(readFileSync(typePath,'utf8'));
function put(path:string,content:string){mkdirSync(dirname(join(storage.dir,path)),{recursive:true});writeFileSync(join(storage.dir,path),content.replace(/from "commander"/g,'from '+JSON.stringify(Bun.resolveSync('commander',root))));}
const runs:any[]=[];

const faults=[{"path":"src/domain/entities/extraction-batch.ts","kind":"omit-version","from":"if (record.version !== 1) fail();","to":"","pattern":"version"},{"path":"src/domain/entities/extraction-batch.ts","kind":"omit-identity-format","from":" || !/^v1:[a-f0-9]{64}$/.test(record.inputIdentity)","to":"","pattern":"identity version|identity case"},{"path":"src/domain/entities/extraction-batch.ts","kind":"omit-canonical-time","from":" || new Date(record.extractedAt).toISOString() !== record.extractedAt","to":"","pattern":"timestamp noncanonical"},{"path":"src/domain/entities/extraction-batch.ts","kind":"allow-unknown-fields","from":"if (Object.keys(value).some(key => !allowed.includes(key))) fail();","to":"","pattern":"unknown"},{"path":"src/domain/entities/extraction-batch.ts","kind":"allow-duplicate-ids","from":" || ids.has(fact.uuid)","to":"","pattern":"duplicate ID"},{"path":"src/domain/entities/extraction-batch.ts","kind":"allow-control-effects","from":" || !types.has(fact.type)","to":"","pattern":"control effect"},{"path":"src/domain/entities/extraction-batch.ts","kind":"omit-outcome-reconciliation","from":"if (result.added !== added || result.updated !== superseded || result.superseded !== superseded) fail();","to":"","pattern":"mismatch"},{"path":"src/domain/entities/extraction-batch.ts","kind":"omit-retirement","from":"retired.add(target);","to":"","pattern":"duplicate supersedence|retired replacement"},{"path":"src/domain/entities/extraction-batch.ts","kind":"allow-reused-replacement","from":"replacements.add(replacement);","to":"","pattern":"reused replacement"},{"path":"src/domain/entities/extraction-batch.ts","kind":"allow-unavailable-replacement","from":"if (!available.has(replacement) || retired.has(replacement) || replacements.has(replacement)) fail();","to":"","pattern":"absent replacement|forward replacement|control replacement"},{"path":"src/domain/entities/extraction-batch.ts","kind":"allow-forward-target","from":"if (ids.has(target) && !available.has(target)) fail();","to":"","pattern":"forward target|control target"},{"path":"src/domain/entities/extraction-batch.ts","kind":"omit-json-validation","from":"assertJson(value);","to":"","pattern":"undefined metadata|nonfinite metadata|getter|sparse array"},{"path":"src/domain/entities/extraction-batch.ts","kind":"alias-input","from":"new ExtractionBatch(JSON.parse(JSON.stringify(value)) as ExtractionBatchRecord)","to":"new ExtractionBatch(value)","pattern":"without aliasing"},{"path":"src/domain/entities/extraction-batch.ts","kind":"alias-output","from":"return JSON.parse(JSON.stringify(this.record)) as ExtractionBatchRecord;","to":"return this.record;","pattern":"without aliasing"},{"path":"src/domain/entities/extraction-batch.ts","kind":"allow-nonobject-metadata","from":"if (Object.hasOwn(fact, \"metadata\")) object(fact.metadata);","to":"","pattern":"metadata array|metadata null"},{"path":"src/domain/entities/extraction-batch.ts","kind":"allow-negative-count","from":" || count < 0","to":"","pattern":"negative count"},{"path":"src/domain/entities/extraction-batch.ts","kind":"allow-unsafe-total","from":"if (!Number.isSafeInteger((result.added as number) + (result.skipped as number))) fail();","to":"","pattern":"unsafe total"}];

try {
 for(const [path,content]of originals){
  for(const match of content.matchAll(/(?:from\s+|import\s*\()\s*["'](\.[^"']+)["']/g)) {
   const target=resolve(dirname(path),match[1]).replace(/\.js$/,'.ts'),local=target.slice(root.length+1).replaceAll('\\','/');
   if(!paths.includes(local))put(local,'export * from '+JSON.stringify(target.replaceAll('\\','/'))+';');
  }
  for(const match of content.matchAll(/source\("([^"]+)"\)/g)){
   const local=match[1].startsWith('src/')?match[1]:'src/'+match[1];if(!paths.includes(local))put(local,'export * from '+JSON.stringify(resolve(local).replaceAll('\\','/'))+';');
  }
 }
 put('capture.ts','import {afterAll} from "bun:test";import {writeFileSync} from "node:fs";afterAll(()=>writeFileSync("coverage.json",JSON.stringify((globalThis as any).__coverage__)));');
 put('bunfig.toml','[test]\ncoverage=false\npreload=['+JSON.stringify(join(root,'tests/test-setup.ts').replaceAll('\\','/'))+(mode==='measure'?',"./capture.ts"':'')+']\n');
 for(const fault of [null,...(mode==='faults'?faults:[])]) {
  for(const [path,content]of originals)put(path,mode==='measure'?instrumentTypeScriptWithCoverage(content,resolve(path)).code:content);
  if(fault){let content=originals.get(fault.path)!;const index=content.indexOf(fault.from);if(index<0)throw Error('Missing fault '+fault.kind);put(fault.path,content.slice(0,index)+fault.to+content.slice(index+fault.from.length));}
  const command=[process.execPath,'test','--timeout','15000',...tests,...(fault?['--test-name-pattern',fault.pattern]:[])];
  const child=Bun.spawnSync(command,{cwd:storage.dir,env:{...process.env,TEMP:storage.dir,TMP:storage.dir,TMPDIR:storage.dir},stdout:'pipe',stderr:'pipe',timeout:180000});
  const output=new TextDecoder().decode(child.stdout)+new TextDecoder().decode(child.stderr);runs.push({fault,command,exit:child.exitCode,output});
  writeFileSync('.git/q100-codec-diagnostic-progress.json',JSON.stringify({runs},null,2));
  if(!fault&&child.exitCode!==0)throw Error('Control failed\n'+output);
  if(fault&&child.exitCode!==0&&!output.includes('(fail)'))throw Error('Fault did not reach assertions\n'+output);
 }
 let measurement;
 if(mode==='measure'){
  const raw=JSON.parse(readFileSync(join(storage.dir,'coverage.json'),'utf8')),map=createCoverageMap(raw);
  measurement={rawCoverage:raw,files:paths.map(path=>{const measured=map.fileCoverageFor(resolve(path)),data=measured.data;return {path,sourceHash:sourceHash(originals.get(path)!),metrics:measured.toSummary().data,uncoveredBranches:Object.entries(data.b).flatMap(([id,hits])=>hits.flatMap((count,index)=>count===0?[{id,index,location:data.branchMap[id]?.locations[index]}]:[])),uncoveredFunctions:Object.entries(data.f).filter(([,hits])=>hits===0).map(([id])=>data.fnMap[id])};})};
  console.log(JSON.stringify(measurement.files.map(file=>({path:file.path,metrics:file.metrics}))));
 }else console.log(JSON.stringify(runs.map(run=>({fault:run.fault?.kind,exit:run.exit}))));
 writeFileSync(`.git/q100-codec-${mode}.json`,JSON.stringify({recordedAt:new Date().toISOString(),runtime:Bun.version,scope:'Scoped diagnostic only; child process instrumentation is not aggregated. No full quality acceptance.',sourceInputs:[...paths.map(path=>({path,sourceHash:sourceHash(originals.get(path)!)})),{path:typePath,sourceHash:typeHash}],runs,measurement,source:readFileSync('.git/q100-codec-diagnostic.ts','utf8')},null,2)+'\n');
} finally { storage.cleanup(); }

